import type { Record } from '../db'
import type { Role } from '../app'

type ApplicationMenuType = {
    /** The label for the menu in the application navigator. */
    title: string
    /** Whether the menu is enabled. */
    active?: boolean
    /** A list of `Role` objects or names of roles that can access the menu. @see {Role} */
    roles?: Array<Role | string>
    /** The menu category that defines the navigation menu style. */
    category?: Record<'sys_app_category'> | string
    /** The tooltip text that appears when a user hovers over the menu. */
    hint?: string
    /** Additional information about what the application does. */
    description?: string
    /** An internal name to differentiate between applications with the same title. */
    name?: string
    /** The relative position of the application menu in the application navigator. */
    order?: number
}

type ApplicationMenu = Now.Internal.WithID<ApplicationMenuType & Now.Internal.Meta>

/**
 * Creates an Application Menu (`sys_app_application`).
 *
 * @see https://docs.servicenow.com/csh?topicname=app-menu-api-now-ts.html&version=latest
 *
 * @param config - an object containing the following properties:
 *   * **$id** - unique id for the record, typically using `Now.ID["value"]`
 *   * **category** - The variable identifier of a menu category that defines the navigation menu style.
 *   * **title** - The label for the menu in the application navigator.
 *   * **active**? - whether the record is enabled
 *   * **description**? - Additional information about what the application does.
 *   * **hint**? - The tooltip text that appears when a user hovers over the menu.
 *   * **name**? - An internal name to differentiate between applications with the same title.
 *   * **order**? - The relative position of the application menu in the application navigator.
 *   * **roles**? - A list of variable identifiers of `Role` objects or names of roles that can access the menu. @see {Role}
 */
export function ApplicationMenu(
    config: ApplicationMenu
): ApplicationMenu & Now.Internal.TableBrand<'sys_app_application'> {
    return config as ApplicationMenu & Now.Internal.TableBrand<'sys_app_application'>
}
